fn find_adverb_position(a0: &str) -> (i64, i64, String)
{
    let mut words = a0.split_whitespace();
    let mut adverb_index = -1;
    for (i, word) in words.enumerate()
    {
        if word.to_lowercase().contains("adv")
        {
            adverb_index = i;
            break;
        }
    }
    if adverb_index == -1
    {
        return (0, 0, String::from("No adverb found"));
    }

    let adverb = words.nth(adverb_index).unwrap();
    let start_pos = words.len();
    let end_pos = adverb_index + 1;
    (start_pos, end_pos, adverb)
}

